-- Emails are stored normalized (trimmed, lower-case) so uniqueness is case-insensitive.
ALTER TABLE "users"
  ADD CONSTRAINT "users_email_normalized_chk"
    CHECK ("email" IS NULL OR "email" = lower(btrim("email")));

-- Only an Argon2id hash can ever be stored: a plaintext password is rejected by the database.
ALTER TABLE "users"
  ADD CONSTRAINT "users_password_hash_format_chk"
    CHECK ("password_hash" IS NULL OR "password_hash" LIKE '$argon2id$v=19$%');

-- Sessions store only the hex SHA-256 of the cookie token, never the token itself.
ALTER TABLE "sessions"
  ADD CONSTRAINT "sessions_token_hash_hex_chk" CHECK ("token_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "sessions_expiry_chk" CHECK ("expires_at" > "created_at");
